self.addEventListener("push",i=>{if(!i.data)return;let n=i.data.json();i.waitUntil(self.registration.showNotification(n.title||"Expense Tracker",{body:n.body||"",icon:"/icon-192.png",data:{url:n.url||"/"}}))}),self.addEventListener("notificationclick",i=>{i.notification.close(),i.waitUntil(self.clients.matchAll({type:"window",includeUncontrolled:!0}).then(n=>{var t;let e=n.find(i=>i.url.includes(self.location.origin));return e?e.focus():self.clients.openWindow((null==(t=i.notification.data)?void 0:t.url)||"/")}))});